  "Import report:": "รายงานการนำเข้า:",
  "Extend the opening database from a PGN file, or from pasted text. Imported data stays in this browser and is added to the built-in ECO openings.":
    "เพิ่มฐานข้อมูลช่องเปิดจากไฟล์หรือข้อความ PGN ข้อมูลจะเก็บในเบราว์เซอร์นี้และรวมกับช่องเปิด ECO ที่มีอยู่",
  "Each game, and optionally each variation inside it, becomes an opening line. Names come from the Opening, Variation or Event tags. Lines that are already in the database are skipped.":
    "แต่ละเกมและรูปแบบย่อยที่เลือกจะกลายเป็นสายช่องเปิด ชื่อมาจากแท็ก Opening, Variation หรือ Event และจะข้ามสายที่มีในฐานข้อมูลแล้ว",
  "The games are counted per opening, with results and decades. Real counts then replace the estimated popularity and history. Only the first 40 half-moves of each game are read.":
    "นับเกมแยกตามช่องเปิด ผลการแข่งขัน และทศวรรษ เพื่อแทนค่าความนิยมและประวัติที่ประเมินไว้ โดยอ่าน 40 ครึ่งตาเดินแรกของแต่ละเกม",
  "Nothing imported yet. The database holds the built-in ECO openings only.":
    "ยังไม่ได้นำเข้าข้อมูล ฐานข้อมูลมีเพียงช่องเปิด ECO ที่มากับเกม",
