  "Score groups, colour balancing and maximum matching avoid repeat opponents whenever a complete pairing without repeats exists. Lowest score gets the bye, preferring players without a previous bye. This game implementation is not FIDE-certified Dutch pairing software.":
    "จับคู่โดยอิงกลุ่มคะแนน ความสมดุลสีหมาก และหลีกเลี่ยงคู่ซ้ำเมื่อทำได้ ผู้มีคะแนนต่ำสุดจะได้บายโดยให้สิทธิ์คนที่ยังไม่เคยได้บายก่อน ระบบนี้ไม่ใช่ซอฟต์แวร์จับคู่ Dutch ที่ FIDE รับรอง",
  "NPC entrants": "ผู้สมัคร NPC",
