    "ทีมละสี่กระดาน สหพันธ์ของคุณกับประเทศชั้นนำสูงสุดเจ็ดประเทศจะเล่นพบกันหมดปีละครั้ง เลือกผู้เล่นที่ยังแข่งขันอยู่และ Elo สูงสุดสี่คน คุณจะเป็นตัวแทนเมื่อได้รับเลือก โดยไม่เปลี่ยน Elo รายบุคคล กระดานที่ว่างนับเป็นแพ้บายเพื่อให้สหพันธ์ขนาดเล็กเข้าร่วมได้",
  "Selected players spend 2 AP and earn $20–160 appearance/prize money. Selected players must register in Tournament before the deadline and play in the event week. Unselected members can follow the simulated exhibition free. Membership is required.":
    "ผู้ได้รับเลือกใช้ 2 AP และได้รับค่าเข้าร่วมหรือเงินรางวัล $20–160 ต้องสมัครก่อนกำหนดและเล่นในสัปดาห์รายการ สมาชิกที่ไม่ได้รับเลือกติดตามการจำลองได้ฟรี โดยต้องเป็นสมาชิกสหพันธ์",
  "National team cup completed.": "รายการถ้วยทีมชาติจบแล้ว",
  "Cup finished this year": "แข่งถ้วยทีมชาติปีนี้แล้ว",
  "You represented your country.": "คุณลงแข่งเป็นตัวแทนประเทศ",
  "You followed your country as a federation member.":
    "คุณติดตามทีมประเทศในฐานะสมาชิกสหพันธ์",
  "Your federation has no eligible players.":
    "สหพันธ์ของคุณไม่มีผู้เล่นที่ผ่านเกณฑ์",
