  "Cancel contract (no refund)": "ยกเลิกสัญญา (ไม่คืนเงิน)",
  "Cancel this contract? There is no refund for unused time.":
    "ต้องการยกเลิกสัญญาหรือไม่? เวลาที่เหลือจะไม่คืนเงิน",
  "One qualifying game remaining": "เหลือบทเรียนสำหรับเกมที่เข้าเกณฑ์หนึ่งเกม",
  "lessons completed": "บทเรียนที่เสร็จแล้ว",
  "% training bonus on time contracts": "% โบนัสฝึกตามสัญญาระยะเวลา",
  "One game: a lesson after your next qualifying game (at least 12 half-moves, or checkmate). Weekly (7 game days) and monthly (30 game days): +10/20/30% session XP by coach level, plus game lessons. Each lesson awards 24/48/72 XP in the specialty. Up to four game lessons per game day. No automatic renewal.":
    "แบบต่อเกมให้บทเรียนหลังเกมถัดไปที่เข้าเกณฑ์ (อย่างน้อย 12 ครึ่งตาเดินหรือรุกจน) สัญญา 7 หรือ 30 วันเพิ่ม XP กิจกรรม 10/20/30% ตามระดับโค้ช พร้อมบทเรียนหลังเกมที่ให้ 24/48/72 XP ในสกิลเฉพาะ สูงสุดวันละสี่บทเรียนและไม่ต่อสัญญาอัตโนมัติ",
  "Work & income": "งานและรายได้",
  "Work ·": "ทำงาน ·",
  "Earn $": "รายได้ $",
  "Available to every player": "ผู้เล่นทุกคนทำได้",
  "Earn outside tournaments. Each job uses today's hours and AP. Up to two jobs per day, each job once. Earnings are recorded in your career ledger.":
    "หารายได้นอกการแข่งขัน แต่ละงานใช้เวลาและ AP ของวันนี้ ทำได้สูงสุดวันละสองงานและงานละหนึ่งครั้ง รายได้บันทึกในบัญชีอาชีพ",
  "{{0}} completed. Earned ${{1}}.": "ทำ {{0}} เสร็จแล้ว ได้รับ ${{1}}",
  "Born into": "สหพันธ์แรกเริ่ม",
  ". Currently representing": "ปัจจุบันเป็นตัวแทน",
  "New federation": "สหพันธ์ใหม่",
  ". Change your in-game representation after 1800 Elo and 25 rated career games. Processing: 30 game days, $250; one transfer per game year. These are career-game rules.":
    "เปลี่ยนสังกัดในเกมได้หลังถึง 1800 Elo และแข่งจัดอันดับ 25 เกม ใช้เวลาดำเนินการ 30 วันในเกมและ $250 เปลี่ยนได้ปีละครั้งตามกฎอาชีพในเกม",
  "Apply · $250": "ยื่นคำขอ · $250",
  "Application:": "คำขอ:",
  "Application submitted. Your current federation stays active during processing.":
    "ส่งคำขอแล้ว ระหว่างดำเนินการยังใช้สหพันธ์ปัจจุบัน",
  "Apply for a federation transfer? The $250 processing fee is non-refundable. Completion cancels and refunds entries restricted to your former federation.":
    "ต้องการยื่นขอเปลี่ยนสหพันธ์หรือไม่? ค่าดำเนินการ $250 ไม่คืน เมื่อเสร็จแล้วจะยกเลิกและคืนเงินรายการที่จำกัดเฉพาะสหพันธ์เดิม",
  "Completed transfers move your home to the new federation's capital, reset membership and refund incompatible national entries. Your existing games, titles, Elo and birthplace remain in your history.":
    "เมื่อย้ายสำเร็จ ที่อยู่จะเปลี่ยนเป็นเมืองหลวงของสหพันธ์ใหม่ รีเซ็ตสมาชิก และคืนค่าสมัครระดับประเทศที่ไม่เข้าเกณฑ์ โดยเก็บเกม ตำแหน่ง Elo และสถานที่เกิดเดิมไว้",
  "You are moving": "คุณกำลังย้ายสังกัด",
  "{{0}} game days remaining": "เหลือ {{0}} วันในเกม",
  "Plan the days before {{0}}": "วางแผนช่วงก่อน {{0}}",
